# Concatenation (row 76's `concat!`), `map` with a later native argument,
# `foreach` and `mapreduce` over native arrays.
#
# Every native argument is snapshotted once in bulk (dense leaves into Julia
# arrays, `FaerSparseMatrix` into `SparseMatrixCSC`), Julia's own kernel runs on
# the snapshots and a dense or sparse native-scalar result is loaded into one
# native owner (see `_native_dense_result`).
#
# Julia cannot dispatch on "some argument is native", so the methods are
# generated by the position of the first native argument: the arguments before
# it are restricted to `_JuliaConcatArg`, which contains no native type. The
# generated methods are therefore pairwise disjoint and every all-Julia call
# keeps Base's and SparseArrays' methods. A first native argument beyond
# `_MAX_JULIA_PREFIX` Julia arguments, or after an argument outside
# `_JuliaConcatArg`, keeps Base's element-wise path.

# Julia arrays that may precede the first native argument.
const _JuliaArrayStorage=Union{Array,SubArray{<:Any,<:Any,<:Array}}
const _JuliaArrayArg=Union{
    Array{<:Number},
    BitArray,
    AbstractRange{<:Number},
    SubArray{<:Number,<:Any,<:Array},
    LinearAlgebra.Adjoint{<:Number,<:_JuliaArrayStorage},
    LinearAlgebra.Transpose{<:Number,<:_JuliaArrayStorage},
    SparseArrays.SparseMatrixCSC{<:Number},
    SparseArrays.SparseVector{<:Number},
    FaerBorrowedArray{<:Number},
    LinearAlgebra.Diagonal{<:Number,<:Vector},
}
const _JuliaConcatArg=Union{Number,_JuliaArrayArg}
# Native arguments. Native vector adjoints are excluded because LinearAlgebra
# owns `hcat` of adjoint vectors (it concatenates their parents, which is
# native already).
const _NativeConcatArg=Union{
    FaerMatrix{<:Number},
    FaerVector{<:Number},
    FaerRow{<:Number},
    FaerView{<:Number,1},
    FaerView{<:Number,2},
    LinearAlgebra.Adjoint{<:Number,<:Union{FaerMatrix,FaerView{<:Any,2}}},
    LinearAlgebra.Transpose{<:Number,<:Union{FaerMatrix,FaerView{<:Any,2}}},
    FaerSparseMatrix{<:Number},
    FaerDiagonal{<:Number},
}
const _NativeTypedConcatFirst=Union{
    FaerRow{<:Number},
    LinearAlgebra.Adjoint{<:Number,<:Union{FaerMatrix,FaerView{<:Any,2}}},
    LinearAlgebra.Transpose{<:Number,<:Union{FaerMatrix,FaerView{<:Any,2}}},
    FaerSparseMatrix{<:Number},
}
const _DenseConcatRest=Union{Number,AbstractVecOrMat{<:Number}}
const _NDConcatRest=Union{Number,AbstractArray{<:Number}}
# 15 leading Julia arguments cover every position of a 4x4 block literal.
const _MAX_JULIA_PREFIX=15

function _native_concat(f, args)
    s=_DenseSnapshots()
    julia=_julia_leaves(s, args)
    return _native_dense_result(s, f(julia...))
end

for k = 0:_MAX_JULIA_PREFIX
    pre=[Symbol(:x, i) for i = 1:k]
    decl=[:($p::_JuliaConcatArg) for p in pre]
    args=:(($(pre...), n, rest...))
    # `T[A B]` and `T[A; B]` with a native matrix, vector or view first already
    # concatenate straight into `similar(A, T, ...)` with bulk block writes.
    typedfirst=k==0 ? :_NativeTypedConcatFirst : :_NativeConcatArg
    @eval begin
        Base.hcat($(decl...), n::_NativeConcatArg, rest::_DenseConcatRest...) =
            _native_concat(hcat, $args)
        Base.vcat($(decl...), n::_NativeConcatArg, rest::_DenseConcatRest...) =
            _native_concat(vcat, $args)
        Base.hvcat(
            rows::Tuple{Vararg{Int}},
            $(decl...),
            n::_NativeConcatArg,
            rest::_DenseConcatRest...,
        ) = _native_concat((xs...) -> hvcat(rows, xs...), $args)
        Base.typed_hcat(::Type{T}, $(decl...), n::$typedfirst, rest::_DenseConcatRest...) where {T} =
            _native_concat((xs...) -> Base.typed_hcat(T, xs...), $args)
        Base.typed_vcat(::Type{T}, $(decl...), n::$typedfirst, rest::_DenseConcatRest...) where {T} =
            _native_concat((xs...) -> Base.typed_vcat(T, xs...), $args)
        Base.typed_hvcat(
            ::Type{T},
            rows::Tuple{Vararg{Int}},
            $(decl...),
            n::_NativeConcatArg,
            rest::_DenseConcatRest...,
        ) where {T} = _native_concat((xs...) -> Base.typed_hvcat(T, rows, xs...), $args)
        Base.cat($(decl...), n::_NativeConcatArg, rest::_NDConcatRest...; dims) =
            _native_concat((xs...) -> cat(xs...; dims), $args)
        Base.hvncat(dim::Int, $(decl...), n::_NativeConcatArg, rest::_NDConcatRest...) =
            _native_concat((xs...) -> hvncat(dim, xs...), $args)
        Base.hvncat(
            shape::Tuple{Vararg{Any}},
            row_first::Bool,
            $(decl...),
            n::_NativeConcatArg,
            rest::_NDConcatRest...,
        ) = _native_concat((xs...) -> hvncat(shape, row_first, xs...), $args)
        Base.typed_hvncat(
            ::Type{T},
            dim::Int,
            $(decl...),
            n::_NativeConcatArg,
            rest::_NDConcatRest...,
        ) where {T} = _native_concat((xs...) -> Base.typed_hvncat(T, dim, xs...), $args)
        Base.typed_hvncat(
            ::Type{T},
            shape::Tuple{Vararg{Any}},
            row_first::Bool,
            $(decl...),
            n::_NativeConcatArg,
            rest::_NDConcatRest...,
        ) where {T} =
            _native_concat((xs...) -> Base.typed_hvncat(T, shape, row_first, xs...), $args)
    end
end

"""
    hcat(As...)
    vcat(As...)
    hvcat(rows, As...)
    cat(As...; dims)
    T[A B; C D]
    [A;; B]

Concatenation (including the array literals and typed literals that lower to
`hcat`, `vcat`, `hvcat`, `hvncat` and their `typed_` forms) in which some
argument is a native array snapshots every native argument once in bulk,
concatenates with Julia's algorithm and returns:

- a [`FaerSparseMatrix`](@ref) (CSC) when the result is sparse and a
  `FaerSparseMatrix` took part (SparseArrays makes any concatenation with a
  sparse operand sparse; Julia sparse with native dense operands stays a
  `SparseMatrixCSC`, as for broadcast);
- a [`FaerVector`](@ref), a [`FaerRow`](@ref) (when every native argument is a
  `FaerRow` and the result has one row) or a [`FaerMatrix`](@ref) for dense
  results of `Float32`, `Float64`, `ComplexF32` or `ComplexF64`;
- otherwise Julia's own result: results with more than two dimensions, or a
  non-native scalar such as `Int[A B]` or `BigFloat[A B]`.

The native argument may follow scalars and Julia arrays (`Array`, `BitArray`,
ranges, `SubArray`s, adjoints and transposes of arrays, `SparseMatrixCSC`,
`SparseVector`, [`FaerBorrowedArray`](@ref)) in up to 15 leading positions,
which covers every position of a 4×4 block literal; calls whose first native
argument comes later or after another array type keep Julia's element-wise
path. Borrowed arrays alone keep Julia results.
"""
Base.hcat(::_NativeConcatArg, ::_DenseConcatRest...)

const _JuliaMapArg=_JuliaArrayArg
const _JuliaMapDest=Union{_JuliaArrayStorage,BitArray,FaerBorrowedArray}
const _MAX_JULIA_MAP_PREFIX=3
for k = 1:_MAX_JULIA_MAP_PREFIX
    pre=[Symbol(:x, i) for i = 1:k]
    decl=[:($p::_JuliaMapArg) for p in pre]
    @eval function Base.map(f, $(decl...), n::_DenseNativeArray, rest::AbstractArray...)
        s=_DenseSnapshots()
        args=_julia_leaves(s, ($(pre...), n, rest...))
        return _native_dense_result(s, map(f, args...))
    end
end
for k = 0:_MAX_JULIA_MAP_PREFIX-1
    pre=[Symbol(:x, i) for i = 1:k]
    decl=[:($p::_JuliaMapArg) for p in pre]
    @eval function Base.map!(
        f,
        dest::_JuliaMapDest,
        $(decl...),
        n::_DenseNativeArray,
        rest::AbstractArray...,
    )
        s=_DenseSnapshots()
        args=_julia_leaves(s, ($(pre...), n, rest...))
        map!(f, dest isa FaerBorrowedArray ? parent(dest) : dest, args...)
        return dest
    end
end

"""
    foreach(f, A, Bs...)

When `A` is a native dense array (or its adjoint or transpose), every native
argument is snapshotted once in bulk before the loop, so `f` sees the values
at the call and changes that `f` makes to `A` do not affect the iteration.
"""
function Base.foreach(f, a::_DenseNativeLeaf, rest...)
    s=_DenseSnapshots()
    args=_julia_leaves(s, (a, rest...))
    foreach(f, args...)
    return nothing
end

"""
    mapreduce(f, op, A; dims=:, init)

A native dense array (or its adjoint or transpose) is snapshotted once in bulk
and Julia's `mapreduce` runs on the snapshot, so `sum(f, A)`, `prod(f, A)`,
`maximum(f, A)` and `minimum(f, A)` reduce in Julia's pairwise order. Reductions
with `dims` return native owners for native scalars. Colmat's native `sum`,
`norm` and `sum(abs2, A)` methods are unchanged.
"""
function Base.mapreduce(f, op, a::_DenseNativeLeaf; kw...)
    s=_DenseSnapshots()
    julia=_julia_leaves(s, (a,))[1]
    return _native_dense_result(s, mapreduce(f, op, julia; kw...))
end
